/* usb_g0.h - Modbus RTU over the USB-C port's virtual COM port (FW-56), through ST's USB device
 * library (CDC class, generated by CubeMX). A frame ends after 2 ms with no new USB packet.
 *
 * In CubeMX's usbd_cdc_if.c, CDC_Receive_FS, USER CODE section:
 *     usb_node_rx(Buf, *Len);
 * (before the generated USBD_CDC_SetRxBuffer / USBD_CDC_ReceivePacket lines). */
#ifndef USB_G0_H
#define USB_G0_H
#include <stdbool.h>
#include <stdint.h>

void usb_node_rx(const uint8_t *buf, uint32_t len);            /* USB interrupt context */
bool usb_take(const uint8_t **frame, uint16_t *len, bool *rx_error, uint32_t now_ms);
void usb_done(const uint8_t *reply, uint16_t len);              /* reply (len 0: none); listen again */

#endif
